// @flow
import path from 'path'
import pify from 'pify'
import { GitCommit, GitTree } from '../models'
import { GitObjectManager, GitIndexManager } from '../managers'
import { read, resolveRef, fs } from '../utils'
/*::
import type { Stats } from 'fs'
import type { CacheEntry } from '../models/GitIndex'
*/

function cacheIsStale (
  { entry, stats } /*: {
    entry: CacheEntry,
    stats: Stats
  } */
) {
  // Comparison based on the description in Paragraph 4 of
  // https://www.kernel.org/pub/software/scm/git/docs/technical/racy-git.txt
  return (
    entry.mode !== stats.mode ||
    entry.mtime.valueOf() !== stats.mtime.valueOf() ||
    entry.ctime.valueOf() !== stats.ctime.valueOf() ||
    entry.uid !== stats.uid ||
    entry.gid !== stats.gid ||
    entry.ino !== stats.ino ||
    entry.size !== stats.size
  )
}

async function getOidAtPath (
  {
    gitdir,
    tree,
    path
  } /*: {
    gitdir: string,
    tree: GitTree,
    path: string|Array<string>
  } */
) {
  if (typeof path === 'string') path = path.split('/')
  let dirname = path.shift()
  for (let entry of tree) {
    if (entry.path === dirname) {
      if (path.length === 0) {
        return entry.oid
      }
      let { type, object } = await GitObjectManager.read({
        gitdir,
        oid: entry.oid
      })
      if (type === 'tree') {
        let tree = GitTree.from(object)
        return getOidAtPath({ gitdir, tree, path })
      }
      if (type === 'blob') {
        throw new Error(`Blob found where tree expected.`)
      }
    }
  }
  return null
}

async function getHeadTree ({ gitdir }) {
  // Get the tree from the HEAD commit.
  let oid = await resolveRef({ gitdir, ref: 'HEAD' })
  let { object: cobject } = await GitObjectManager.read({ gitdir, oid })
  let commit = GitCommit.from(cobject)
  let { object: tobject } = await GitObjectManager.read({
    gitdir,
    oid: commit.parseHeaders().tree
  })
  let tree = GitTree.from(tobject).entries()
  return tree
}

// For now we're just diffing individual files
export async function status (
  {
    workdir,
    gitdir,
    pathname
  } /*: {
    workdir: string,
    gitdir: string,
    pathname: string
  } */
) {
  let headTree = await getHeadTree({ gitdir })
  let treeOid = await getOidAtPath({ gitdir, tree: headTree, path: pathname })
  let indexEntry = null
  // Acquire a lock on the index
  await GitIndexManager.acquire(`${gitdir}/index`, async function (index) {
    for (let entry of index) {
      if (entry.path === pathname) {
        indexEntry = entry
        break
      }
    }
  })
  let stats = null
  try {
    stats = await pify(fs().lstat)(path.join(workdir, pathname))
  } catch (err) {
    if (err.code !== 'ENOENT') {
      throw err
    }
  }

  if (treeOid === null && stats === null) {
    if (indexEntry === null) {
      return 'absent'
    } else {
      return '*absent'
    }
  } else if (treeOid !== null && stats === null) {
    if (indexEntry === null) {
      return 'deleted'
    } else {
      return '*deleted'
    }
  } else if (treeOid === null && stats !== null) {
    if (indexEntry === null) {
      return '*added'
    } else {
      let object = await read(path.join(workdir, pathname))
      let workdirOid = await GitObjectManager.hash({
        gitdir,
        type: 'blob',
        object
      })
      return workdirOid === indexEntry.oid ? 'added' : '*added'
    }
  } else {
    let object = await read(path.join(workdir, pathname))
    let workdirOid = await GitObjectManager.hash({
      gitdir,
      type: 'blob',
      object
    })
    if (workdirOid === treeOid) {
      if (indexEntry === null) return '*unmodified'
      return workdirOid === indexEntry.oid ? 'unmodified' : '*unmodified'
    }
    if (indexEntry === null) return '*modified'
    return workdirOid === indexEntry.oid ? 'modified' : '*modified'
  }
}

import {
  init,
  clone,
  checkout,
  list,
  add,
  remove,
  commit,
  verify,
  pack,
  unpack,
  push,
  fetch,
  getConfig,
  setConfig,
  status,
  findRoot,
  listBranches
} from './commands'

import ChainedMap from 'flipchain'

export default function git (dir) {
  return (dir === undefined) ? new Git() : new Git().workdir(dir).gitdir(`${dir}/.git`)
}

// The class is merely a fluent command/query builder
class Git extends ChainedMap {
  // @constructor
  constructor (parent) {
    super(parent)
    this.extend([
      'workdir',
      'gitdir',
      'remote',
      'branch',
      'author',
      'email',
      'datetime',
      'depth',
      'timestamp',
      'signingKey',
      'verificationKey',
      'outputStream',
      'inputStream',
      'username',
      'password',
      'url',
      'outputStream',
      'inputStream'
    ])
  }
  /**
   * @param {string} username
   * @param {string} password
   * @returns {Git} this
   *
   * Use with {@link #gitpush .push} and {@link #gitpull .pull} to set Basic Authentication headers.
   * This works for basic username / password auth, or the newer username / token auth
   * that is often required if 2FA is enabled.
   */
  auth (username, password) {
    // Allow specifying it as one argument (mostly for CLI inputability)
    if (password === undefined) {
      let i = username.indexOf(':')
      if (i > -1) {
        password = username.slice(i + 1)
        username = username.slice(0, i)
      } else {
        password = '' // Enables the .auth(GITHUB_TOKEN) no-username shorthand
      }
    }
    this.set('username', username)
    this.set('password', password)
    return this
  }
  /**
   * @param {string} company
   * @param {string} token
   * @returns {Git} this
   *
   * Use with {@link #gitpush .push} and {@link #gitpull .pull} to set Basic Authentication headers.
   * This for is for *actual* OAuth2 tokens (not "personal access tokens").
   * Unfortunately, all the major git hosting companies have chosen different conventions!
   * Lucky for you, I already looked up and codified it for you.
   *
   * - oauth2('github', token) - Github uses `token` as the username, and 'x-oauth-basic' as the password.
   * - oauth2('bitbucket', token) - Bitbucket uses 'x-token-auth' as the username, and `token` as the password.
   * - oauth2('gitlab', token) - Gitlab uses 'oauth2' as the username, and `token` as the password.
   *
   * I will gladly accept pull requests for more companies' conventions.
   */
  oauth2 (company, token) {
    switch (company) {
      case 'github':
        this.set('username', token)
        this.set('password', 'x-oauth-basic')
        break
      case 'bitbucket':
        this.set('username', 'x-token-auth')
        this.set('password', token)
        break
      case 'gitlab':
        this.set('username', 'oauth2')
        this.set('password', token)
        break
      default:
        throw new Error(
          `I don't know how ${company} expects its Basic Auth headers to be formatted for OAuth2 usage. If you do, you can use the regular '.auth(username, password)' to set the basic auth header yourself.`
        )
    }
    return this
  }
