import path from 'path'
import pify from 'pify'
import { GitCommit, GitTree } from '../models'
import { GitObjectManager, GitIndexManager } from '../managers'
import { write, resolveRef, fs } from '../utils'

async function writeTreeToDisk ({ gitdir, workdir, index, prefix, tree }) {
  for (let entry of tree) {
    let { type, object } = await GitObjectManager.read({
      gitdir,
      oid: entry.oid
    })
    let entrypath = prefix === '' ? entry.path : `${prefix}/${entry.path}`
    let filepath = path.join(workdir, prefix, entry.path)
    switch (type) {
      case 'blob':
        await write(filepath, object)
        let stats = await pify(fs().lstat)(filepath)
        index.insert({
          filepath: entrypath,
          stats,
          oid: entry.oid
        })
        break
      case 'tree':
        let tree = GitTree.from(object)
        await writeTreeToDisk({
          gitdir,
          workdir,
          index,
          prefix: entrypath,
          tree
        })
        break
      default:
        throw new Error(
          `Unexpected object type ${type} found in tree for '${entrypath}'`
        )
    }
  }
}

export async function checkout ({ workdir, gitdir, remote, ref }) {
  // Get tree oid
  let oid
  try {
    oid = await resolveRef({ gitdir, ref })
  } catch (e) {
    oid = await resolveRef({ gitdir, ref: `${remote}/${ref}` })
    await write(`${gitdir}/refs/heads/${ref}`, oid + '\n')
  }
  let commit = await GitObjectManager.read({ gitdir, oid })
  if (commit.type !== 'commit') {
    throw new Error(`Unexpected type: ${commit.type}`)
  }
  let comm = GitCommit.from(commit.object.toString('utf8'))
  let sha = comm.headers().tree
  // Get top-level tree
  let { type, object } = await GitObjectManager.read({ gitdir, oid: sha })
  if (type !== 'tree') throw new Error(`Unexpected type: ${type}`)
  let tree = GitTree.from(object)
  // Acquire a lock on the index
  await GitIndexManager.acquire(`${gitdir}/index`, async function (index) {
    index.clear()
    // Write files. TODO: Write them atomically
    await writeTreeToDisk({ gitdir, workdir, index, prefix: '', tree })
    // Update HEAD TODO: Handle non-branch cases
    write(`${gitdir}/HEAD`, `ref: refs/heads/${ref}`)
  })
}

// @flow
import stream from 'stream'
import thru from 'thru'
import { getConfig } from './getConfig'
import { unpack } from './unpack'
import { GitRemoteHTTP, GitRefsManager, GitShallowManager } from '../managers'
import { GitPktLine } from '../models'
import { resolveRef, pkg } from '../utils'

export async function fetchPackfile ({
  gitdir,
  ref,
  remote,
  authUsername,
  authPassword,
  depth = 0
}) {
  let url = await getConfig({
    gitdir,
    path: `remote.${remote}.url`
  })
  let remoteHTTP = new GitRemoteHTTP(url)
  if (authUsername !== undefined && authPassword !== undefined) {
    remoteHTTP.auth = {
      username: authUsername,
      password: authPassword
    }
  }
  await remoteHTTP.preparePull()
  // Check server supports shallow cloning
  if (depth > 0 && !remoteHTTP.capabilities.has('shallow')) {
    throw new Error(`Remote does not support shallow fetching`)
  }
  await GitRefsManager.updateRemoteRefs({
    gitdir,
    remote,
    refs: remoteHTTP.refs,
    symrefs: remoteHTTP.symrefs
  })
  let want = await resolveRef({ gitdir, ref: `refs/remotes/${remote}/${ref}` })
  // Note: I removed "ofs-delta" from the capabilities list and now
  // Github uses all ref-deltas when I fetch packfiles instead of all ofs-deltas. Nice!
  const capabilities = `multi_ack_detailed no-done side-band-64k thin-pack agent=git/${pkg.name}@${pkg.version}`
  let packstream = new stream.PassThrough()
  packstream.write(GitPktLine.encode(`want ${want} ${capabilities}\n`))
  let oids = await GitShallowManager.read({ gitdir })
  if (oids.size > 0 && remoteHTTP.capabilities.has('shallow')) {
    for (let oid of oids) {
      packstream.write(GitPktLine.encode(`shallow ${oid}\n`))
    }
  }
  if (depth !== 0) {
    packstream.write(GitPktLine.encode(`deepen ${parseInt(depth)}\n`))
  }
  packstream.write(GitPktLine.flush())
  let have = null
  try {
    have = await resolveRef({ gitdir, ref })
  } catch (err) {}
  if (have) {
    packstream.write(GitPktLine.encode(`have ${have}\n`))
    packstream.write(GitPktLine.flush())
  }
  packstream.end(GitPktLine.encode(`done\n`))
  let response = await remoteHTTP.pull(packstream)
  response.packetlines.pipe(
    thru(async (data, next) => {
      let line = data.toString('utf8')
      if (line.startsWith('shallow')) {
        let oid = line.slice(-41).trim()
        if (oid.length !== 40) {
          throw new Error(`non-40 character 'shallow' oid: ${oid}`)
        }
        oids.add(oid)
        await GitShallowManager.write({ gitdir, oids })
      } else if (line.startsWith('unshallow')) {
        let oid = line.slice(-41).trim()
        if (oid.length !== 40) {
          throw new Error(`non-40 character 'shallow' oid: ${oid}`)
        }
        oids.delete(oid)
        await GitShallowManager.write({ gitdir, oids })
      }
      next(null, data)
    })
  )
  return response
}

export async function fetch ({
  gitdir,
  ref = 'HEAD',
  remote,
  authUsername,
  authPassword,
  depth = 0
}) {
  let response = await fetchPackfile({
    gitdir,
    ref,
    remote,
    authUsername,
    authPassword,
    depth
  })
  response.progress.on('data', data => console.log(data.toString('utf8')))
  await unpack({ gitdir, inputStream: response.packfile })
}

// @flow
import stream from 'stream'
import { config } from './config'
import { GitRemoteHTTP } from '../managers'
import { listCommits } from './listCommits'
import { listObjects } from './listObjects'
import { pack } from './pack'
import { GitPktLine } from '../models'
import { resolveRef } from '../utils'

export async function push ({
  gitdir,
  ref,
  remote,
  url,
  authUsername,
  authPassword
}) {
  // TODO: Figure out how pushing tags works. (This only works for branches.)
  remote = remote || 'origin'
  if (url === undefined) {
    url = await config({
      gitdir,
      path: `remote.${remote}.url`
    })
  }
  let fullRef = ref.startsWith('refs/') ? ref : `refs/heads/${ref}`
  let oid = await resolveRef({ gitdir, ref })
  let httpRemote = new GitRemoteHTTP(url)
  if (authUsername !== undefined && authPassword !== undefined) {
    httpRemote.auth = {
      username: authUsername,
      password: authPassword
    }
  }
  await httpRemote.preparePush()
  let commits = await listCommits({
    gitdir,
    start: [oid],
    finish: httpRemote.refs.values()
  })
  let objects = await listObjects({ gitdir, oids: commits })
  let packstream = new stream.PassThrough()
  let oldoid =
    httpRemote.refs.get(fullRef) || '0000000000000000000000000000000000000000'
  packstream.write(
    GitPktLine.encode(`${oldoid} ${oid} ${fullRef}\0 report-status\n`)
  )
  packstream.write(GitPktLine.flush())
  pack({
    gitdir,
    oids: [...objects],
    outputStream: packstream
  })
  let response = await httpRemote.push(packstream)
  return response
}

// @flow
import { GitObjectManager } from '../managers'
import { GitCommit } from '../models'
import { resolveRef } from '../utils'

export async function log ({
  gitdir,
  ref = 'HEAD',
  depth,
  since // Date
}) {
  let sinceTimestamp = since === undefined ? undefined : Math.floor(since.valueOf() / 1000)
  // TODO: In the future, we may want to have an API where we return a
  // async iterator that emits commits.
  let commits = []
  let start = await resolveRef({ gitdir, ref })
  let {type, object} = await GitObjectManager.read({ gitdir, oid: start })
  if (type !== 'commit') throw new Error(`The given ref ${ref} did not resolve to a commit but to a ${type}`)
  let currentCommit = { oid: start, ...GitCommit.from(object).parse() }
  commits.push(currentCommit)
  while (true) {
    if (depth !== undefined && commits.length === depth) break
    if (currentCommit.parent.length === 0) break
    let oid = currentCommit.parent[0]
    let {type, object} = await GitObjectManager.read({ gitdir, oid })
    if (type !== 'commit') throw new Error(`Invalid commit parent ${currentCommit.parent[0]} is of type ${type}`)
    currentCommit = { oid, ...GitCommit.from(object).parse() }
    if (sinceTimestamp !== undefined && currentCommit.author.timestamp <= sinceTimestamp) break
    commits.push(currentCommit)
  }
  return commits
}

