import fs from 'fs'
import { existsSync } from 'fs'
import { lock, unlock, sleep } from '../dist/for-node/utils'
import { createTempDir } from 'jest-fixtures'

describe('lockfile', () => {
  test('make lockfile', async () => {
    let dir = await createTempDir()
    await lock(dir)
    expect(existsSync(`${dir}.lock`)).toBe(true)
  })

  test('cannot double-acquire lockfile', async () => {
    let dir = await createTempDir()
    await lock(dir)
    expect(existsSync(`${dir}.lock`)).toBe(true)
    try {
      await lock(dir)
      throw new Error('Double-acquired lock')
    } catch (err) {}
  })

  test('can release lockfile', async () => {
    let dir = await createTempDir()
    await lock(dir)
    expect(existsSync(`${dir}.lock`)).toBe(true)
    await unlock(dir)
    await lock(dir)
    expect(existsSync(`${dir}.lock`)).toBe(true)
    await unlock(dir)
    await sleep(100)
    expect(existsSync(`${dir}.lock`)).toBe(false)
  })

  test('cannot double-release lockfile', async () => {
    let dir = await createTempDir()
    await lock(dir)
    expect(existsSync(`${dir}.lock`)).toBe(true)
    await unlock(dir)
    try {
      await unlock(dir)
      throw new Error('Was able to double-release lockfile')
    } catch (err) {}
  })

  test('can retry until acquire lockfile', async () => {
    let dir = await createTempDir()
    await lock(dir)
    expect(existsSync(`${dir}.lock`)).toBe(true)
    setTimeout(() => fs.rmdir(`${dir}.lock`), 100)
    try {
      await lock(dir)
    } catch (err) {
      throw new Error('Could not acquire lock even after lockfile deleted.')
    }
  })
})

// @flow
import ignore from 'ignore'
import path from 'path'
import { read } from '../utils'

// I'm putting this in a Manager because I reckon it could benefit
// from a LOT of cacheing.

export class GitIgnoreManager {
  static async isIgnored ({ gitdir, workdir, pathname }) /*: Promise<Boolean> */{
    let pairs = [{
      gitignore: path.join(workdir, '.gitignore'),
      pathname
    }]
    let pieces = pathname.split('/')
    for (let i = 1; i < pieces.length; i++) {
      let dir = pieces.slice(0, i).join('/')
      let file = pieces.slice(i).join('/')
      pairs.push({
        gitignore: path.join(workdir, dir, '.gitignore'),
        pathname: file
      })
    }
    let ignoredStatus = false
    for (let p of pairs) {
      let file
      try {
        file = await read(p.gitignore, 'utf8')
      } catch (err) {
        if (err.code === 'NOENT') continue
      }
      let ign = ignore().add(file)
      // If the parent directory is excluded, we are done.
      // "It is not possible to re-include a file if a parent directory of that file is excluded. Git doesn’t list excluded directories for performance reasons, so any patterns on contained files have no effect, no matter where they are defined."
      // source: https://git-scm.com/docs/gitignore
      let parentdir = path.dirname(p.pathname)
      if (ign.ignores(parentdir)) return true
      // If the file is currently ignored, test for UNignoring.
      if (ignoredStatus) {
        if (!ignore().add(`**\n${file}`).ignores(p.pathname)) {
          ignoredStatus = false
        }
      } else {
        ignoredStatus = ign.ignores(p.pathname)
      }
    }
    return ignoredStatus
  }
}

