    this.operateAuthorDateTime = date
    return this
  }
  depth (depth) {
    this.operateDepth = parseInt(depth)
    return this
  }
  timestamp (seconds) {
    // seconds since unix epoch
    this.operateAuthorTimestamp = seconds
    return this
  }
  signingKey (asciiarmor) {
    this.privateKeys = asciiarmor
    return this
  }
  verificationKey (asciiarmor) {
    this.publicKeys = asciiarmor
    return this
  }
  outputStream (stream) {
    this.outputStream = stream
    return this
  }
  inputStream (stream) {
    this.inputStream = stream
    return this
  }
  async init () {
    await init(this.gitdir)
  }
  async fetch (ref) {
    await fetch({
      gitdir: this.gitdir,
      ref,
      depth: this.operateDepth,
      remote: this.operateRemote,
      authUsername: this.operateUsername,
      authPassword: this.operatePassword
    })
  }
  async checkout (ref) {
    await checkout({
      workdir: this.workdir,
      gitdir: this.gitdir,
      ref,
      remote: this.operateRemote
    })
  }
  async clone (url) {
    await init(this.gitdir)
    // Add remote
    await setConfig({
      gitdir: this.gitdir,
      path: 'remote.origin.url',
      value: url
    })
    // Fetch commits
    await fetch({
      gitdir: this.gitdir,
      ref: `refs/heads/${this.operateBranch}`,
      depth: this.operateDepth,
      remote: this.operateRemote,
      authUsername: this.operateUsername,
      authPassword: this.operatePassword
    })
    // Checkout branch
    await checkout({
      workdir: this.workdir,
      gitdir: this.gitdir,
      ref: this.operateBranch,
      remote: this.operateRemote
    })
  }
  async list () {
    return list({
      gitdir: this.gitdir
    })
  }
  async add (filepath) {
    return add({
      gitdir: this.gitdir,
      workdir: this.workdir,
      filepath
    })
  }
  async remove (filepath) {
    return remove({
      gitdir: this.gitdir,
      filepath
    })
  }
  async commit (message) {
    return commit({
      gitdir: this.gitdir,
      author: {
        name: this.operateAuthorName || (await this.getConfig('user.name')),
        email: this.operateAuthorEmail || (await this.getConfig('user.email')),
        timestamp: this.operateAuthorTimestamp,
        date: this.operateAuthorDateTime
      },
      committer: {
        name: this.operateAuthorName || (await this.getConfig('user.name')),
        email: this.operateAuthorEmail || (await this.getConfig('user.email')),
        timestamp: this.operateAuthorTimestamp,
        date: this.operateAuthorDateTime
      },
      message,
      privateKeys: this.privateKeys
    })
  }
  async verify (ref) {
    return verify({
      gitdir: this.gitdir,
      publicKeys: this.publicKeys,
      ref
    })
  }
  async pack (oids) {
    return pack({
      gitdir: this.gitdir,
      outputStream: this.outputStream,
      oids
    })
  }
  async unpack (oids) {
    return unpack({
      gitdir: this.gitdir,
      inputStream: this.inputStream
    })
  }
  async push (ref) {
    let url = await getConfig({
      gitdir: this.gitdir,
      path: `remote.${this.operateRemote}.url`
    })
    console.log('url =', url)
    return push({
      gitdir: this.gitdir,
      ref,
      url,
      authUsername: this.operateUsername,
      authPassword: this.operatePassword
    })
  }
  async pull (ref) {
    return fetch({
      gitdir: this.gitdir,
      ref,
      remote: this.operateRemote,
      authUsername: this.operateUsername,
      authPassword: this.operatePassword
    })
  }
  async getConfig (path) {
    return getConfig({
      gitdir: this.gitdir,
      path
    })
  }
  async setConfig (path, value) {
    return setConfig({
      gitdir: this.gitdir,
      path,
      value
    })
  }
  async status (pathname) {
    return status({
      gitdir: this.gitdir,
      workdir: this.workdir,
      pathname
    })
  }
}

