//@flow
import path from 'path'
import pify from 'pify'
import { GitCommit, GitTree } from '../models'
import { GitObjectManager, GitIndexManager } from '../managers'
import { read, resolveRef, fs } from '../utils'
/*::
import type { Stats } from 'fs'
import type { CacheEntry } from '../models/GitIndex'
*/

function cacheIsStale ({entry, stats} /*: {entry: CacheEntry, stats: Stats} */) {
  // Comparison based on the description in Paragraph 4 of
  // https://www.kernel.org/pub/software/scm/git/docs/technical/racy-git.txt
  return (
    (entry.mode !== stats.mode) ||
    (entry.mtime.valueOf() !== stats.mtime.valueOf()) ||
    (entry.ctime.valueOf() !== stats.ctime.valueOf()) ||
    (entry.uid !== stats.uid) ||
    (entry.gid !== stats.gid) ||
    (entry.ino !== stats.ino) ||
    (entry.size !== stats.size)
  )
}

async function getOidAtPath ({gitdir, tree, path} /*: {gitdir: string, tree: GitTree, path: string|Array<string> } */) {
  if (typeof path === 'string') path = path.split('/')
  let dirname = path.shift()
  for (let entry of tree) {
    if (entry.path === dirname) {
      if (path.length === 0) {
        return entry.oid
      }
      let {type, object} = await GitObjectManager.read({gitdir, oid: entry.oid})
      if (type === 'tree') {
        let tree = GitTree.from(object)
        return getOidAtPath({gitdir, tree, path})
      }
      if (type === 'blob') {
        throw new Error(`Blob found where tree expected.`)
      }
    }
  }
  return null
}

async function getHeadTree ({gitdir}) {
  // Get the tree from the HEAD commit.
  let oid = await resolveRef({gitdir, ref: 'HEAD'})
  let {object: cobject} = await GitObjectManager.read({gitdir, oid})
  let commit = GitCommit.from(cobject)
  let {object: tobject} = await GitObjectManager.read({gitdir, oid: commit.parseHeaders().tree})
  let tree = GitTree.from(tobject).entries()
  return tree
}

// For now we're just diffing individual files
export async function status ({ workdir, gitdir, pathname }/*: { workdir: string, gitdir: string, pathname: string } */) {
  let headTree = await getHeadTree({gitdir})
  let treeOid = await getOidAtPath({gitdir, tree: headTree, path: pathname})
  let indexEntry = null
  // Acquire a lock on the index
  await GitIndexManager.acquire(`${gitdir}/index`, async function (index) {
    for (let entry of index) {
      if (entry.path === pathname) {
        indexEntry = entry
        break
      }
    }
  })
  let stats = null
  try {
    stats = await pify(fs().lstat)(path.join(workdir, pathname))
  } catch (err) {
    if (err.code !== 'ENOENT') {
      throw err
    }
  }

  if (treeOid === null && stats === null) {
    if (indexEntry === null) {
      return 'absent'
    } else {
      return '*absent'
    }
  } else if (treeOid !== null && stats === null) {
    if (indexEntry === null) {
      return 'deleted'
    } else {
      return '*deleted'
    }
  } else if (treeOid === null && stats !== null) {
    if (indexEntry === null) {
      return '*added'
    } else {
      let object = await read(path.join(workdir, pathname))
      let workdirOid = await GitObjectManager.hash({gitdir, type: 'blob', object})
      return (workdirOid === indexEntry.oid) ? 'added' : '*added'
    }
  } else {
    let object = await read(path.join(workdir, pathname))
    let workdirOid = await GitObjectManager.hash({gitdir, type: 'blob', object})
    if (workdirOid === treeOid) {
      if (indexEntry === null) return '*unmodified'
      return (workdirOid === indexEntry.oid) ? 'unmodified' : '*unmodified'
    }
    if (indexEntry === null) return '*modified'
    return (workdirOid === indexEntry.oid) ? 'modified' : '*modified'
  }
}

import path from 'path'
import pify from 'pify'
import { GitCommit, GitTree } from '../models'
import { GitObjectManager, GitIndexManager } from '../managers'
import { write, resolveRef, fs } from '../utils'

async function writeTreeToDisk ({ gitdir, workdir, index, prefix, tree }) {
  for (let entry of tree) {
    let { type, object } = await GitObjectManager.read({
      gitdir,
      oid: entry.oid
    })
    let entrypath = path.posix.join(prefix, entry.path)
    let filepath = path.join(workdir, prefix, entry.path)
    switch (type) {
      case 'blob':
        await write(filepath, object)
        let stats = await pify(fs().lstat)(filepath)
        index.insert({
          filepath: entrypath,
          stats,
          oid: entry.oid
        })
        break
      case 'tree':
        let tree = GitTree.from(object)
        await writeTreeToDisk({
          gitdir,
          workdir,
          index,
          prefix: entrypath,
          tree
        })
        break
      default:
        throw new Error(
          `Unexpected object type ${type} found in tree for '${entrypath}'`
        )
    }
  }
}

export async function checkout ({ workdir, gitdir, remote, ref }) {
  // Get tree oid
  let oid
  try {
    oid = await resolveRef({ gitdir, ref })
  } catch (e) {
    oid = await resolveRef({ gitdir, ref: `${remote}/${ref}` })
    await write(`${gitdir}/refs/heads/${ref}`, oid + '\n')
  }
  let commit = await GitObjectManager.read({ gitdir, oid })
  if (commit.type !== 'commit') {
    throw new Error(`Unexpected type: ${commit.type}`)
  }
  let comm = GitCommit.from(commit.object.toString('utf8'))
  let sha = comm.headers().tree
  // Get top-level tree
  let { type, object } = await GitObjectManager.read({ gitdir, oid: sha })
  if (type !== 'tree') throw new Error(`Unexpected type: ${type}`)
  let tree = GitTree.from(object)
  // Acquire a lock on the index
  await GitIndexManager.acquire(`${gitdir}/index`, async function (index) {
    index.clear()
    // Write files. TODO: Write them atomically
    await writeTreeToDisk({ gitdir, workdir, index, prefix: '', tree })
    // Update HEAD TODO: Handle non-branch cases
    write(`${gitdir}/HEAD`, `ref: refs/heads/${ref}`)
  })
}

