// @flow
// This is a convenience wrapper for reading and writing files in the 'refs' directory.
import path from 'path'
import { write } from '../utils'

export class GitRefsManager {
  static async updateRemoteRefs ({ gitdir, remote, refs, symrefs }) {
    // Validate input
    for (let [key, value] of refs) {
      if (!value.match(/[0-9a-f]{40}/)) {
        throw new Error(`Unexpected ref contents: '${value}'`)
      }
    }
    // Combine refs and symrefs giving symrefs priority
    let actualRefsToWrite = new Map()
    for (let [key, value] of refs) actualRefsToWrite.set(key, value)
    for (let [key, value] of symrefs) {
      let branch = value.replace(/^refs\/heads\//, '')
      actualRefsToWrite.set(key, `ref: refs/remotes/${remote}/${branch}`)
    }
    // Update files
    const normalizeValue = value => value.trim() + '\n'
    for (let [key, value] of actualRefsToWrite) {
      // For some reason we trim these
      key = key.replace(/^refs\/heads\//, '')
      key = key.replace(/^refs\/tags\//, '')
      await write(
        path.join(gitdir, 'refs', 'remotes', remote, key),
        normalizeValue(value),
        'utf8'
      )
    }
  } /*: {
    gitdir: string,
    remote: string,
    refs: Map<string, string>,
    symrefs: Map<string, string>
  } */
}

// @flow
import { Buffer } from 'buffer'
import { GitObjectManager } from '../managers'
import listpack from 'git-list-pack'
import thru from 'thru'
import peek from 'buffer-peek-stream'
import applyDelta from 'git-apply-delta'
/*::
import type {Writable} from 'stream'
*/

const types = {
  1: 'commit',
  2: 'tree',
  3: 'blob',
  4: 'tag',
  6: 'ofs-delta',
  7: 'ref-delta'
}

function parseVarInt (buffer /*: Buffer */) {
  let n = 0
  for (var i = 0; i < buffer.byteLength; i++) {
    n = (buffer[i] & 0b01111111) + (n << 7)
    if ((buffer[i] & 0b10000000) === 0) {
      if (i !== buffer.byteLength - 1) throw new Error('Invalid varint buffer')
      return n
    }
  }
  throw new Error('Invalid varint buffer')
}

// TODO: Move this to 'plumbing'
export async function unpack (
  {
    gitdir,
    inputStream,
    onprogress
  } /*: {gitdir: string, inputStream: ReadableStream, onprogress: Function} */
) {
  return new Promise(function (resolve, reject) {
    // Read header
    peek(inputStream, 12, (err, data, inputStream) => {
      if (err) return reject(err)
      let iden = data.slice(0, 4).toString('utf8')
      if (iden !== 'PACK') {
        throw new Error(`Packfile started with '${iden}'. Expected 'PACK'`)
      }
      let ver = data.slice(4, 8).toString('hex')
      if (ver !== '00000002') {
        throw new Error(`Unknown packfile version '${ver}'. Expected 00000002.`)
      }
      // Read a 4 byte (32-bit) int
      let numObjects = data.readInt32BE(8)
      if (onprogress !== undefined) {
        onprogress({ loaded: 0, total: numObjects, lengthComputable: true })
      }
      if (numObjects === 0) return resolve()
      // And on our merry way
      let offsetMap = new Map()
      inputStream
        .pipe(listpack())
        .pipe(
          thru(async ({ data, type, reference, offset, num }, next) => {
            type = types[type]
            if (type === 'ref-delta') {
              let oid = Buffer.from(reference).toString('hex')
              try {
                let { object, type } = await GitObjectManager.read({
                  gitdir,
                  oid
                })
                let result = applyDelta(data, object)
                let newoid = await GitObjectManager.write({
                  gitdir,
                  type,
                  object: result
                })
                // console.log(`${type} ${newoid} ref-delta ${oid}`)
                offsetMap.set(offset, newoid)
              } catch (err) {
                throw new Error(
                  `Could not find object ${reference} ${oid} that is referenced by a ref-delta object in packfile at byte offset ${offset}.`
                )
              }
            } else if (type === 'ofs-delta') {
              // Note: this might be not working because offsets might not be
              // guaranteed to be on object boundaries? In which case we'd need
              // to write the packfile to disk first, I think.
              // For now I've "solved" it by simply not advertising ofs-delta as a capability
              // during the HTTP request, so Github will only send ref-deltas not ofs-deltas.
              let absoluteOffset = offset - parseVarInt(reference)
              let referenceOid = offsetMap.get(absoluteOffset)
              // console.log(`${offset} ofs-delta ${absoluteOffset} ${referenceOid}`)
              let { type, object } = await GitObjectManager.read({
                gitdir,
                oid: referenceOid
              })
              let result = applyDelta(data, object)
              let oid = await GitObjectManager.write({
                gitdir,
                type,
                object: result
              })
              // console.log(`${offset} ${type} ${oid} ofs-delta ${referenceOid}`)
              offsetMap.set(offset, oid)
            } else {
              let oid = await GitObjectManager.write({
                gitdir,
                type,
                object: data
              })
              // console.log(`${offset} ${type} ${oid}`)
              offsetMap.set(offset, oid)
            }
            if (onprogress !== undefined) {
              onprogress({
                loaded: numObjects - num,
                total: numObjects,
                lengthComputable: true
              })
            }
            if (num === 0) return resolve()
            next(null)
          })
        )
        .on('error', reject)
        .on('finish', resolve)
    })
  })
}

import test from 'ava'
import fs from 'fs'
import { tmpdir, exists } from './helpers'
import { lock, unlock, sleep } from '../dist/for-node/utils'

test('make lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
})

test('cannot double-acquire lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  try {
    await lock(dir)
    t.fail('Double-acquired lock')
  } catch (err) {
    t.pass()
  }
})

test('can release lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  await unlock(dir)
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  await unlock(dir)
  await sleep(100)
  t.false(exists(`${dir}.lock`))
})

test('cannot double-release lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  await unlock(dir)
  try {
    await unlock(dir)
    t.fail('Was able to double-release lockfile')
  } catch (err) {
    t.pass()
  }
})

test('can retry until acquire lockfile', async t => {
  let dir = await tmpdir()
  await lock(dir)
  t.true(exists(`${dir}.lock`))
  setTimeout(() => fs.rmdir(`${dir}.lock`), 100)
  try {
    await lock(dir)
    t.pass()
  } catch (err) {
    t.fail('Could not acquire lock even after lockfile deleted.')
  }
})

import { init } from './init'
import { setConfig } from './setConfig'
import { fetch } from './fetch'
import { checkout } from './checkout'

export async function clone ({
  workdir,
  gitdir,
  url,
  remote,
  ref,
  depth,
  authUsername,
  authPassword
}) {
  remote = remote || 'origin'
  await init({ gitdir })
  // Add remote
  await setConfig({
    gitdir,
    path: `remote.${remote}.url`,
    value: url
  })
  // Fetch commits
  await fetch({
    gitdir,
    ref,
    depth,
    remote,
    authUsername,
    authPassword
  })
  // Checkout branch
  await checkout({
    workdir,
    gitdir,
    ref,
    remote
  })
}

#!/usr/bin/env node
const minimisted = require('minimisted')
const git = require('.')

// This really isn't much of a CLI. It's mostly for testing.
// But it's very versatile and works surprisingly well.

minimisted(async function ({ _: [command, ...args], ...opts }) {
  const dir = process.cwd()
  const repo = git(dir)
  let cmd = `git('${dir}')`
  for (let key of Object.keys(opts)) {
    // This is how you check for an array, right?
    if (opts[key].length === undefined) {
      repo[key](opts[key])
      cmd += `.${key}('${opts[key]}')`
    } else {
      repo[key](...opts[key])
      cmd += `.${key}(${opts[key].map(x => `'${x}'`).join(', ')})`
    }
  }
  cmd += `.${command}(${args.map(x => `'${x}'`).join(', ')})`
  console.log(cmd)
  let result = await repo[command](...args)
  console.log(result)
})

