} from './commands'

export default function git (dir) {
  return dir === undefined
    ? new Git()
    : new Git().workdir(dir).gitdir(`${dir}/.git`)
}

const extend = (self, array) => {
  for (let fn of array) {
    self[fn] = val => self.set(fn, val)
  }
}

// The class is merely a fluent command/query builder
class Git extends Map {
  // @constructor
  constructor (parent) {
    super(parent)
    extend(this, [
      'workdir',
      'gitdir',
      'remote',
      'branch',
      'author',
      'email',
      'datetime',
      'depth',
      'timestamp',
      'signingKey',
      'verificationKey',
      'outputStream',
      'inputStream',
      'username',
      'password',
      'url',
      'outputStream',
      'inputStream'
    ])
  }
  /**
   * @param {string} username
   * @param {string} password
   * @returns {Git} this
   *
   * Use with {@link #gitpush .push} and {@link #gitpull .pull} to set Basic Authentication headers.
   * This works for basic username / password auth, or the newer username / token auth
   * that is often required if 2FA is enabled.
   */
  auth (username, password) {
    // Allow specifying it as one argument (mostly for CLI inputability)
    if (password === undefined) {
      let i = username.indexOf(':')
      if (i > -1) {
        password = username.slice(i + 1)
        username = username.slice(0, i)
      } else {
        password = '' // Enables the .auth(GITHUB_TOKEN) no-username shorthand
      }
    }
    this.set('username', username)
    this.set('password', password)
    return this
  }
  /**
   * @param {string} company
   * @param {string} token
   * @returns {Git} this
   *
   * Use with {@link #gitpush .push} and {@link #gitpull .pull} to set Basic Authentication headers.
   * This for is for *actual* OAuth2 tokens (not "personal access tokens").
   * Unfortunately, all the major git hosting companies have chosen different conventions!
   * Lucky for you, I already looked up and codified it for you.
   *
   * - oauth2('github', token) - Github uses `token` as the username, and 'x-oauth-basic' as the password.
   * - oauth2('bitbucket', token) - Bitbucket uses 'x-token-auth' as the username, and `token` as the password.
   * - oauth2('gitlab', token) - Gitlab uses 'oauth2' as the username, and `token` as the password.
   *
   * I will gladly accept pull requests for more companies' conventions.
   */
  oauth2 (company, token) {
    switch (company) {
      case 'github':
        this.set('username', token)
        this.set('password', 'x-oauth-basic')
        break
      case 'bitbucket':
        this.set('username', 'x-token-auth')
        this.set('password', token)
        break
      case 'gitlab':
        this.set('username', 'oauth2')
        this.set('password', token)
        break
      default:
        throw new Error(
          `I don't know how ${company} expects its Basic Auth headers to be formatted for OAuth2 usage. If you do, you can use the regular '.auth(username, password)' to set the basic auth header yourself.`
        )
    }
    return this
  }
  async findRoot (dir) {
    return findRoot(dir)
  }
  async init () {
    await init({
      gitdir: this.get('gitdir')
    })
  }
  async fetch (ref) {
    await fetch({
      gitdir: this.get('gitdir'),
      ref,
      url: this.get('url'),
      depth: this.get('depth'),
      remote: this.get('remote'),
      authUsername: this.get('username'),
      authPassword: this.get('password')
    })
  }
  async checkout (ref) {
    await checkout({
      workdir: this.get('workdir'),
      gitdir: this.get('gitdir'),
      ref,
      remote: this.get('remote')
    })
  }
  async clone (url) {
    await clone({
      workdir: this.get('workdir'),
      gitdir: this.get('gitdir'),
      url,
      remote: this.get('remote'),
      ref: this.get('branch'),
      depth: this.get('depth'),
      authUsername: this.get('username'),
      authPassword: this.get('password')
    })
  }
  async list () {
    return list({
      gitdir: this.get('gitdir')
    })
  }
  async add (filepath) {
    return add({
      gitdir: this.get('gitdir'),
      workdir: this.get('workdir'),
      filepath
    })
  }
  async remove (filepath) {
    return remove({
      gitdir: this.get('gitdir'),
      filepath
    })
  }
  async commit (message) {
    return commit({
      gitdir: this.get('gitdir'),
      author: {
        name: this.get('author'),
        email: this.get('email'),
        timestamp: this.get('timestamp'),
        date: this.get('datetime')
      },
      committer: {
        name: this.get('author'),
        email: this.get('email'),
        timestamp: this.get('timestamp'),
        date: this.get('datetime')
      },
      message,
      privateKeys: this.get('signingKey')
    })
  }
  async verify (ref) {
    return verify({
      gitdir: this.get('gitdir'),
      publicKeys: this.get('verificationKey'),
      ref
    })
  }
  async pack (oids) {
    return pack({
      gitdir: this.get('gitdir'),
      outputStream: this.get('outputStream'),
      oids
    })
  }
  async unpack (oids) {
    return unpack({
      gitdir: this.get('gitdir'),
      inputStream: this.get('inputStream')
    })
  }
  async push (ref) {
    return push({
      gitdir: this.get('gitdir'),
      ref,
      remote: this.get('remote'),
      url: this.get('url'),
      authUsername: this.get('username'),
      authPassword: this.get('password')
    })
  }
  async pull (ref) {
    return fetch({
      gitdir: this.get('gitdir'),
      ref,
      remote: this.get('remote'),
      authUsername: this.get('username'),
      authPassword: this.get('password')
    })
  }
  async config (path, value) {
    if (arguments.length === 1) {
      return config({
        gitdir: this.get('gitdir'),
        path
      })
    } else {
      return config({
        gitdir: this.get('gitdir'),
        path,
        value
      })
    }
  }
  async status (pathname) {
    return status({
      gitdir: this.get('gitdir'),
      workdir: this.get('workdir'),
      pathname
    })
  }
  async listBranches () {
    return listBranches({
      gitdir: this.get('gitdir')
    })
  }
}

// @flow
// This is a convenience wrapper for reading and writing files in the 'refs' directory.
import path from 'path'
import { write } from '../utils'

export class GitRefsManager {
  static async updateRemoteRefs (
    {
      gitdir,
      remote,
      refs,
      symrefs
    } /*: {
      gitdir: string,
      remote: string,
      refs: Map<string, string>,
      symrefs: Map<string, string>
    } */
  ) {
    // Validate input
    for (let [key, value] of refs) {
      if (!value.match(/[0-9a-f]{40}/)) {
        throw new Error(`Unexpected ref contents: '${value}'`)
      }
    }
    // Combine refs and symrefs giving symrefs priority
    let actualRefsToWrite = new Map()
    for (let [key, value] of refs) actualRefsToWrite.set(key, value)
    for (let [key, value] of symrefs) {
      let branch = value.replace(/^refs\/heads\//, '')
      actualRefsToWrite.set(key, `ref: refs/remotes/${remote}/${branch}`)
    }
    // Update files
    const normalizeValue = value => value.trim() + '\n'
    for (let [key, value] of actualRefsToWrite) {
      // For some reason we trim these
      key = key.replace(/^refs\/heads\//, '')
      key = key.replace(/^refs\/tags\//, '')
      await write(
        path.join(gitdir, 'refs', 'remotes', remote, key),
        normalizeValue(value),
        'utf8'
      )
    }
  }
}

import {
  init,
  checkout,
  list,
  add,
  remove,
  commit,
  verify,
  pack,
  unpack,
  push,
  fetch,
  getConfig,
  setConfig,
  status,
  findRoot
} from './commands'

export default function git (dir) {
  return new Git(dir)
}

// The class is merely a fluent command/query builder
class Git {
  constructor (dir) {
    if (dir) {
      this.workdir = dir
      this.gitdir = `${dir}/.git`
    }
    this.operateRemote = 'origin'
    this.operateDepth = 0
    this.operateBranch = 'master'
  }
  workdir (dir) {
    this.workdir = dir
    return this
  }
  gitdir (dir) {
    this.gitdir = dir
    return this
  }
  // This form works for basic username / password auth, or
  // the newer username / token auth that is often required if
  // 2FA is enabled.
  auth (username, password) {
    // Allow specifying it as one argument (mostly for CLI inputability)
    if (password === undefined) {
      let i = username.indexOf(':')
      if (i > -1) {
        password = username.slice(i + 1)
        username = username.slice(0, i)
      }
    }
    this.operateUsername = username
    this.operatePassword = password || '' // Enables the .auth(GITHUB_TOKEN) no-username shorthand
    return this
  }
  // This for is for actual OAuth2 uses. Unfortunately, the
  // major players all have different conventions.
  oauth2 (company, token) {
    switch (company) {
      case 'github':
        this.operateUsername = token
        this.operatePassword = 'x-oauth-basic'
        break
      case 'bitbucket':
        this.operateUsername = 'x-token-auth'
        this.operatePassword = token
        break
      case 'gitlab':
        this.operateUsername = 'oauth2'
        this.operatePassword = token
        break
      default:
        throw new Error(
          `I don't know how ${company} expects its Basic Auth headers to be formatted for OAuth2 usage. If you do, you can use the regular '.auth(username, password)' to set the basic auth header yourself.`
        )
    }
    return this
  }
  remote (name) {
    this.operateRemote = name
    return this
  }
  author (name) {
    this.operateAuthorName = name
    return this
  }
  branch (name) {
    this.operateBranch = name
    return this
  }
  email (email) {
    this.operateAuthorEmail = email
    return this
  }
  datetime (date) {
    this.operateAuthorDateTime = date
    return this
  }
  depth (depth) {
    this.operateDepth = parseInt(depth)
    return this
  }
  timestamp (seconds) {
    // seconds since unix epoch
    this.operateAuthorTimestamp = seconds
    return this
  }
  signingKey (asciiarmor) {
    this.privateKeys = asciiarmor
    return this
  }
  verificationKey (asciiarmor) {
    this.publicKeys = asciiarmor
    return this
  }
  outputStream (stream) {
    this.outputStream = stream
    return this
  }
  inputStream (stream) {
    this.inputStream = stream
    return this
  }
  onProgress (callback) {
    this.operateOnProgress = callback
    return this
  }
  async findRoot (dir) {
    return findRoot(dir)
  }
  async init () {
    await init(this.gitdir)
  }
  async fetch (ref) {
    await fetch({
      gitdir: this.gitdir,
      ref,
      depth: this.operateDepth,
      remote: this.operateRemote,
      authUsername: this.operateUsername,
      authPassword: this.operatePassword
    })
  }
  async checkout (ref) {
    await checkout({
      workdir: this.workdir,
      gitdir: this.gitdir,
      ref,
      remote: this.operateRemote
    })
  }
  async clone (url) {
    await init(this.gitdir)
    // Add remote
    await setConfig({
      gitdir: this.gitdir,
      path: 'remote.origin.url',
      value: url
    })
    // Fetch commits
    await fetch({
      gitdir: this.gitdir,
      ref: `refs/heads/${this.operateBranch}`,
      depth: this.operateDepth,
      remote: this.operateRemote,
      authUsername: this.operateUsername,
      authPassword: this.operatePassword
    })
    // Checkout branch
    await checkout({
      workdir: this.workdir,
      gitdir: this.gitdir,
      ref: this.operateBranch,
      remote: this.operateRemote
    })
  }
  async list () {
    return list({
      gitdir: this.gitdir
    })
  }
  async add (filepath) {
    return add({
      gitdir: this.gitdir,
      workdir: this.workdir,
      filepath
    })
  }
  async remove (filepath) {
    return remove({
      gitdir: this.gitdir,
      filepath
    })
  }
  async commit (message) {
    return commit({
      gitdir: this.gitdir,
      author: {
        name: this.operateAuthorName || (await this.getConfig('user.name')),
        email: this.operateAuthorEmail || (await this.getConfig('user.email')),
        timestamp: this.operateAuthorTimestamp,
        date: this.operateAuthorDateTime
      },
      committer: {
        name: this.operateAuthorName || (await this.getConfig('user.name')),
        email: this.operateAuthorEmail || (await this.getConfig('user.email')),
        timestamp: this.operateAuthorTimestamp,
        date: this.operateAuthorDateTime
      },
      message,
      privateKeys: this.privateKeys
    })
  }
  async verify (ref) {
    return verify({
      gitdir: this.gitdir,
      publicKeys: this.publicKeys,
      ref
    })
  }
  async pack (oids) {
    return pack({
      gitdir: this.gitdir,
      outputStream: this.outputStream,
      oids
    })
  }
  async unpack (oids) {
    return unpack({
      gitdir: this.gitdir,
      inputStream: this.inputStream,
      onProgress: this.operateOnProgress
    })
  }
  async push (ref) {
    let url = await getConfig({
      gitdir: this.gitdir,
      path: `remote.${this.operateRemote}.url`
    })
    return push({
      gitdir: this.gitdir,
      ref,
      url,
      authUsername: this.operateUsername,
      authPassword: this.operatePassword
    })
  }
  async pull (ref) {
    return fetch({
      gitdir: this.gitdir,
      ref,
      remote: this.operateRemote,
      authUsername: this.operateUsername,
      authPassword: this.operatePassword,
      onProgress: this.operateOnProgress
    })
  }
  async getConfig (path) {
    return getConfig({
      gitdir: this.gitdir,
      path
    })
  }
  async setConfig (path, value) {
    return setConfig({
      gitdir: this.gitdir,
      path,
      value
    })
  }
  async status (pathname) {
    return status({
      gitdir: this.gitdir,
      workdir: this.workdir,
      pathname
    })
  }
}

