import git from '..'
import { read } from '../dist/for-node/utils'
import { existsSync } from 'fs'

import { copyFixtureIntoTempDir } from 'jest-fixtures'

jest.setTimeout(60000)

describe('fetch', () => {
  test('fetch (from Github)', async () => {
    // Setup
    let clientDir = await copyFixtureIntoTempDir(__dirname, 'test-fetch.git')
    // Test
    await git()
      .gitdir(clientDir)
      .remote('origin')
      .fetch('refs/heads/master')
  })

  test('shallow fetch (from Github)', async () => {
    // Setup
    let clientDir = await copyFixtureIntoTempDir(__dirname, 'test-fetch.git')
    // Test
    await git()
      .gitdir(clientDir)
      .depth(1)
      .remote('origin')
      .fetch('refs/heads/test-branch-shallow-clone')
    expect(existsSync(`${clientDir}/shallow`)).toBe(true)
    let shallow = await read(`${clientDir}/shallow`, { encoding: 'utf8' })
    expect(shallow === '92e7b4123fbf135f5ffa9b6fe2ec78d07bbc353e\n').toBe(true)
    // Now test deepen
    await git()
      .gitdir(clientDir)
      .depth(2)
      .remote('origin')
      .fetch('refs/heads/test-branch-shallow-clone')
    shallow = await read(`${clientDir}/shallow`, { encoding: 'utf8' })
    expect(shallow === '86ec153c7b48e02f92930d07542680f60d104d31\n').toBe(true)
  })
})

// @flow
import stream from 'stream'
import { GitRemoteHTTP } from '../managers'
import { listCommits } from './listCommits'
import { listObjects } from './listObjects'
import { pack } from './pack'
import { GitPktLine } from '../models'
import { resolveRef } from '../utils'

export async function push ({
  gitdir,
  ref,
  url,
  authUsername,
  authPassword
}) {
  // TODO: Figure out how pushing tags works. (This only works for branches.)
  let fullRef = ref.startsWith('refs/') ? ref : `refs/heads/${ref}`
  let oid = await resolveRef({ gitdir, ref })
  let remote = new GitRemoteHTTP(url)
  if (authUsername !== undefined && authPassword !== undefined) {
    remote.auth = {
      username: authUsername,
      password: authPassword
    }
  }
  await remote.preparePush()
  let commits = await listCommits({
    gitdir,
    start: [oid],
    finish: remote.refs.values()
  })
  let objects = await listObjects({ gitdir, oids: commits })
  let packstream = new stream.PassThrough()
  let oldoid =
    remote.refs.get(fullRef) || '0000000000000000000000000000000000000000'
  packstream.write(
    GitPktLine.encode(`${oldoid} ${oid} ${fullRef}\0 report-status\n`)
  )
  packstream.write(GitPktLine.flush())
  pack({
    gitdir,
    oids: [...objects],
    outputStream: packstream
  })
  let response = await remote.push(packstream)
  return response
}

import git from '..'
import path from 'path'
import { read, write, rm } from '../dist/for-node/utils'
import { copyFixtureIntoTempDir } from 'jest-fixtures'

describe('status', () => {
  test('status', async () => {
    let gitdir = await copyFixtureIntoTempDir(__dirname, 'test-status.git')
    let workdir = await copyFixtureIntoTempDir(__dirname, 'test-status')
    const repo = git()
      .gitdir(gitdir)
      .workdir(workdir)
    const a = await repo.status('a.txt')
    const b = await repo.status('b.txt')
    const c = await repo.status('c.txt')
    const d = await repo.status('d.txt')
    const e = await repo.status('e.txt')
    expect(a).toEqual('unmodified')
    expect(b).toEqual('*modified')
    expect(c).toEqual('*deleted')
    expect(d).toEqual('*added')
    expect(e).toBe('absent')

    await repo.add('a.txt')
    await repo.add('b.txt')
    await repo.remove('c.txt')
    await repo.add('d.txt')
    const a2 = await repo.status('a.txt')
    const b2 = await repo.status('b.txt')
    const c2 = await repo.status('c.txt')
    const d2 = await repo.status('d.txt')
    expect(a2).toEqual('unmodified')
    expect(b2).toEqual('modified')
    expect(c2).toEqual('deleted')
    expect(d2).toEqual('added')

    // And finally the weirdo cases
    let acontent = await read(path.join(workdir, 'a.txt'))
    await write(path.join(workdir, 'a.txt'), 'Hi')
    await repo.add('a.txt')
    await write(path.join(workdir, 'a.txt'), acontent)
    let a3 = await repo.status('a.txt')
    expect(a3).toEqual('*unmodified')

    await write(path.join(workdir, 'e.txt'), 'Hi')
    await repo.add('e.txt')
    await rm(path.join(workdir, 'e.txt'))
    let e3 = await repo.status('e.txt')
    expect(e3).toEqual('*absent')
  })
})

// @flow
import path from 'path'
import pify from 'pify'
import { resolveRef } from './resolveRef'
import { GitCommit, GitTree } from '../models'
import { GitObjectManager, GitIndexManager, GitIgnoreManager } from '../managers'
import { read, fs } from '../utils'
/*::
import type { Stats } from 'fs'
import type { CacheEntry } from '../models/GitIndex'
*/

function cacheIsStale (
  { entry, stats } /*: {
    entry: CacheEntry,
    stats: Stats
  } */
) {
  // Comparison based on the description in Paragraph 4 of
  // https://www.kernel.org/pub/software/scm/git/docs/technical/racy-git.txt
  return (
    entry.mode !== stats.mode ||
    entry.mtime.valueOf() !== stats.mtime.valueOf() ||
    entry.ctime.valueOf() !== stats.ctime.valueOf() ||
    entry.uid !== stats.uid ||
    entry.gid !== stats.gid ||
    entry.ino !== stats.ino ||
    entry.size !== stats.size
  )
}

async function getOidAtPath (
  {
    gitdir,
    tree,
    path
  } /*: {
    gitdir: string,
    tree: GitTree,
    path: string|Array<string>
  } */
) {
  if (typeof path === 'string') path = path.split('/')
  let dirname = path.shift()
  for (let entry of tree) {
    if (entry.path === dirname) {
      if (path.length === 0) {
        return entry.oid
      }
      let { type, object } = await GitObjectManager.read({
        gitdir,
        oid: entry.oid
      })
      if (type === 'tree') {
        let tree = GitTree.from(object)
        return getOidAtPath({ gitdir, tree, path })
      }
      if (type === 'blob') {
        throw new Error(`Blob found where tree expected.`)
      }
    }
  }
  return null
}

async function getHeadTree ({ gitdir }) {
  // Get the tree from the HEAD commit.
  let oid = await resolveRef({ gitdir, ref: 'HEAD' })
  let { object: cobject } = await GitObjectManager.read({ gitdir, oid })
  let commit = GitCommit.from(cobject)
  let { object: tobject } = await GitObjectManager.read({
    gitdir,
    oid: commit.parseHeaders().tree
  })
  let tree = GitTree.from(tobject).entries()
  return tree
}

// For now we're just diffing individual files
export async function status (
  {
    workdir,
    gitdir,
    pathname
  } /*: {
    workdir: string,
    gitdir: string,
    pathname: string
  } */
) {
  let ignored = await GitIgnoreManager.isIgnored({ gitdir, workdir, pathname })
  if (ignored) {
    return 'ignored'
  }
  let headTree = await getHeadTree({ gitdir })
  let treeOid = await getOidAtPath({ gitdir, tree: headTree, path: pathname })
  let indexEntry = null
  // Acquire a lock on the index
  await GitIndexManager.acquire(`${gitdir}/index`, async function (index) {
    for (let entry of index) {
      if (entry.path === pathname) {
        indexEntry = entry
        break
      }
    }
  })
  let stats = null
  try {
    stats = await pify(fs().lstat)(path.join(workdir, pathname))
  } catch (err) {
    if (err.code !== 'ENOENT') {
      throw err
    }
  }

  if (treeOid === null && stats === null) {
    if (indexEntry === null) {
      return 'absent'
    } else {
      return '*absent'
    }
  } else if (treeOid !== null && stats === null) {
    if (indexEntry === null) {
      return 'deleted'
    } else {
      return '*deleted'
    }
  } else if (treeOid === null && stats !== null) {
    if (indexEntry === null) {
      return '*added'
    } else {
      let object = await read(path.join(workdir, pathname))
      let workdirOid = await GitObjectManager.hash({
        gitdir,
        type: 'blob',
        object
      })
      return workdirOid === indexEntry.oid ? 'added' : '*added'
    }
  } else {
    let object = await read(path.join(workdir, pathname))
    let workdirOid = await GitObjectManager.hash({
      gitdir,
      type: 'blob',
      object
    })
    if (workdirOid === treeOid) {
      if (indexEntry === null) return '*unmodified'
      return workdirOid === indexEntry.oid ? 'unmodified' : '*unmodified'
    }
    if (indexEntry === null) return '*modified'
    return workdirOid === indexEntry.oid ? 'modified' : '*modified'
  }
}

