      .fetch('refs/heads/test-branch-shallow-clone')
    expect(exists(`${clientDir}/shallow`)).toBe(true)
    let shallow = await read(`${clientDir}/shallow`, { encoding: 'utf8' })
    expect(shallow === '92e7b4123fbf135f5ffa9b6fe2ec78d07bbc353e\n').toBe(true)
    // Now test deepen
    await git()
      .gitdir(clientDir)
      .depth(2)
      .remote('origin')
      .fetch('refs/heads/test-branch-shallow-clone')
    shallow = await read(`${clientDir}/shallow`, { encoding: 'utf8' })
    expect(shallow === '86ec153c7b48e02f92930d07542680f60d104d31\n').toBe(true)
  })
})

import git from '..'
import pify from 'pify'
import ncp from 'ncp'
import { tmpdir } from './__helpers__'

describe('add', () => {
  test('file', async () => {
    // Setup
    let dir = await tmpdir()
    console.log('dir =', dir)
    await pify(ncp)('__tests__/__fixtures__/test-add', dir)
    // Test
    const repo = git(dir)
    await repo.init()
    let orig = (await repo.list()).length
    await repo.add('a.txt')
    expect((await repo.list()).length === 1).toBe(true)
    await repo.add('a.txt')
    expect((await repo.list()).length === 1).toBe(true)
    await repo.add('a-copy.txt')
    expect((await repo.list()).length === 2).toBe(true)
    await repo.add('b.txt')
    expect((await repo.list()).length === 3).toBe(true)
  })
})

