import git from '..'
import fs from 'fs'
import { GitObjectManager } from '../dist/for-node/managers'
import path from 'path'
import { createTempDir } from 'jest-fixtures'

describe('unpack', () => {
  test('unpack', async () => {
    let dir = await createTempDir()
    await git(dir).init()
    let fixture = fs.createReadStream(
      '__tests__/__fixtures__/test-pack/foobar-76178ca22ef818f971fca371d84bce571d474b1d.pack'
    )
    await git(dir)
      .inputStream(fixture)
      .unpack()
    const oids = [
      '5a9da3272badb2d3c8dbab463aed5741acb15a33',
      '0bfe8fa3764089465235461624f2ede1533e74ec',
      '414a0afa7e20452d90ab52de1c024182531c5c52',
      '97b32c43e96acc7873a1990e409194cb92421522',
      '328e74b65839f7e5a8ae3b54e0b49180a5b7b82b',
      'fdba2ad440c231d15a2179f729b4b50ab5860df2',
      '5171f8a8291d7edc31a6670800d5967cfd6be830',
      '7983b4770a894a068152dfe6f347ea9b5ae561c5',
      'f03ae7b490022507f83729b9227e723ab1587a38',
      'a59efbcd7640e659ec81887a2599711f8d9ef801',
      'e5abf40a5b37382c700f51ac5c2aeefdadb8e184',
      '5477471ab5a6a8f2c217023532475044117a8f2c'
    ]
    for (let oid of oids) {
      let filepath = path.join(
        dir,
        '.git',
        'objects',
        oid.slice(0, 2),
        oid.slice(2)
      )
      let e = fs.existsSync(filepath)
      expect(e).toBe(true)
      let { type, object } = await GitObjectManager.read({
        gitdir: path.join(dir, '.git'),
        oid
      })
      expect(typeof type === 'string').toBe(true)
      expect(Buffer.isBuffer(object)).toBe(true)
    }
  })
})

// @flow
import stream from 'stream'
import thru from 'thru'
import { config } from './config'
import { unpack } from './unpack'
import { GitRemoteHTTP, GitRefsManager, GitShallowManager } from '../managers'
import { GitPktLine } from '../models'
import { resolveRef, pkg } from '../utils'

export async function fetchPackfile ({
  gitdir,
  ref,
  remote,
  url,
  authUsername,
  authPassword,
  depth = null,
  since = null,
  exclude = [],
  relative = false
}) {
  if (depth !== null) {
    if (Number.isNaN(parseInt(depth))) throw new Error(`Invalid value for depth argument: ${depth}`)
    depth = parseInt(depth)
  }
  remote = remote || 'origin'
  if (url === undefined) {
    url = await config({
      gitdir,
      path: `remote.${remote}.url`
    })
  }
  let remoteHTTP = new GitRemoteHTTP(url)
  if (authUsername !== undefined && authPassword !== undefined) {
    remoteHTTP.auth = {
      username: authUsername,
      password: authPassword
    }
  }
  await remoteHTTP.preparePull()
  // Check server supports shallow cloning
  if (depth !== null && !remoteHTTP.capabilities.has('shallow')) {
    throw new Error(`Remote does not support shallow fetches`)
  }
  if (since !== null && !remoteHTTP.capabilities.has('deepen-since')) {
    throw new Error(`Remote does not support shallow fetches by date`)
  }
  if (exclude.length > 0 && !remoteHTTP.capabilities.has('deepen-not')) {
    throw new Error(`Remote does not support shallow fetches excluding commits reachable by refs`)
  }
  if (relative === true && !remoteHTTP.capabilities.has('deepen-relative')) {
    throw new Error(`Remote does not support shallow fetches relative to the current shallow depth`)
  }
  await GitRefsManager.updateRemoteRefs({
    gitdir,
    remote,
    refs: remoteHTTP.refs,
    symrefs: remoteHTTP.symrefs
  })
  let want = await resolveRef({ gitdir, ref: `refs/remotes/${remote}/${ref}` })
  // Note: I removed "ofs-delta" from the capabilities list and now
  // Github uses all ref-deltas when I fetch packfiles instead of all ofs-deltas. Nice!
  const capabilities = `multi_ack_detailed no-done side-band-64k thin-pack agent=git/${pkg.name}@${pkg.version}${relative ? ' deepen-relative' : ''}`
  let packstream = new stream.PassThrough()
  packstream.write(GitPktLine.encode(`want ${want} ${capabilities}\n`))
  let oids = await GitShallowManager.read({ gitdir })
  if (oids.size > 0 && remoteHTTP.capabilities.has('shallow')) {
    for (let oid of oids) {
      packstream.write(GitPktLine.encode(`shallow ${oid}\n`))
    }
  }
  if (depth !== null) {
    packstream.write(GitPktLine.encode(`deepen ${depth}\n`))
  }
  if (since !== null) {
    packstream.write(GitPktLine.encode(`deepen-since ${Math.floor(since.valueOf() / 1000)}\n`))
  }
  for (let x of exclude) {
    packstream.write(GitPktLine.encode(`deepen-not ${x}\n`))
  }
  packstream.write(GitPktLine.flush())
  let have = null
  try {
    have = await resolveRef({ gitdir, ref })
  } catch (err) {}
  if (have) {
    packstream.write(GitPktLine.encode(`have ${have}\n`))
    packstream.write(GitPktLine.flush())
  }
  packstream.end(GitPktLine.encode(`done\n`))
  let response = await remoteHTTP.pull(packstream)
  response.packetlines.pipe(
    thru(async (data, next) => {
      let line = data.toString('utf8')
      if (line.startsWith('shallow')) {
        let oid = line.slice(-41).trim()
        if (oid.length !== 40) {
          throw new Error(`non-40 character 'shallow' oid: ${oid}`)
        }
        oids.add(oid)
        await GitShallowManager.write({ gitdir, oids })
      } else if (line.startsWith('unshallow')) {
        let oid = line.slice(-41).trim()
        if (oid.length !== 40) {
          throw new Error(`non-40 character 'shallow' oid: ${oid}`)
        }
        oids.delete(oid)
        await GitShallowManager.write({ gitdir, oids })
      }
      next(null, data)
    })
  )
  return response
}

export async function fetch ({
  gitdir,
  ref = 'HEAD',
  remote,
  url,
  authUsername,
  authPassword,
  depth,
  since,
  exclude,
  relative
}) {
  let response = await fetchPackfile({
    gitdir,
    ref,
    remote,
    url,
    authUsername,
    authPassword,
    depth,
    since,
    exclude,
    relative
  })
  response.progress.on('data', data => console.log(data.toString('utf8')))
  await unpack({ gitdir, inputStream: response.packfile })
}

// @flow
import stream from 'stream'
import thru from 'thru'
import { getConfig } from './getConfig'
import { unpack } from './unpack'
import { GitRemoteHTTP, GitRefsManager, GitShallowManager } from '../managers'
import { GitPktLine } from '../models'
import { resolveRef, pkg } from '../utils'

export async function fetchPackfile ({
  gitdir,
  ref = 'HEAD',
  remote,
  authUsername,
  authPassword,
  depth = 0
}) {
  let url = await getConfig({
    gitdir,
    path: `remote.${remote}.url`
  })
  let remoteHTTP = new GitRemoteHTTP(url)
  if (authUsername !== undefined && authPassword !== undefined) {
    remoteHTTP.auth = {
      username: authUsername,
      password: authPassword
    }
  }
  await remoteHTTP.preparePull()
  // Check server supports shallow cloning
  if (depth > 0 && !remoteHTTP.capabilities.has('shallow')) {
    throw new Error(`Remote does not support shallow fetching`)
  }
  await GitRefsManager.updateRemoteRefs({
    gitdir,
    remote,
    refs: remoteHTTP.refs
  })
  let want = remoteHTTP.refs.get(ref)
  // Note: I removed "ofs-delta" from the capabilities list and now
  // Github uses all ref-deltas when I fetch packfiles instead of all ofs-deltas. Nice!
  const capabilities = `multi_ack_detailed no-done side-band-64k thin-pack agent=git/${pkg.name}@${pkg.version}`
  let packstream = new stream.PassThrough()
  packstream.write(GitPktLine.encode(`want ${want} ${capabilities}\n`))
  let oids = await GitShallowManager.read({ gitdir })
  if (oids.size > 0 && remoteHTTP.capabilities.has('shallow')) {
    for (let oid of oids) {
      packstream.write(GitPktLine.encode(`shallow ${oid}\n`))
    }
  }
  if (depth !== 0) {
    packstream.write(GitPktLine.encode(`deepen ${parseInt(depth)}\n`))
  }
  packstream.write(GitPktLine.flush())
  let have = null
  try {
    have = await resolveRef({ gitdir, ref })
  } catch (err) {
    console.log("Looks like we don't have that ref yet.")
  }
  if (have) {
    packstream.write(GitPktLine.encode(`have ${have}\n`))
    packstream.write(GitPktLine.flush())
  }
  packstream.end(GitPktLine.encode(`done\n`))
  let response = await remoteHTTP.pull(packstream)
  response.packetlines.pipe(
    thru(async (data, next) => {
      let line = data.toString('utf8')
      if (line.startsWith('shallow')) {
        let oid = line.slice(-41).trim()
        if (oid.length !== 40) {
          throw new Error(`non-40 character 'shallow' oid: ${oid}`)
        }
        oids.add(oid)
        await GitShallowManager.write({ gitdir, oids })
      } else if (line.startsWith('unshallow')) {
        let oid = line.slice(-41).trim()
        if (oid.length !== 40) {
          throw new Error(`non-40 character 'shallow' oid: ${oid}`)
        }
        oids.delete(oid)
        await GitShallowManager.write({ gitdir, oids })
      }
      next(null, data)
    })
  )
  return response
}

export async function fetch ({
  gitdir,
  ref = 'HEAD',
  remote,
  authUsername,
  authPassword,
  depth = 0,
  onProgress
}) {
  let response = await fetchPackfile({
    gitdir,
    ref,
    remote,
    authUsername,
    authPassword,
    depth
  })
  response.progress.on('data', data => console.log(data.toString('utf8')))
  await unpack({ gitdir, inputStream: response.packfile, onProgress })
}

import path from 'path'
import babel from 'rollup-plugin-babel'
import json from 'rollup-plugin-json'
import resolve from 'rollup-plugin-node-resolve'
import commonjs from 'rollup-plugin-commonjs'
import pkg from './package.json'

const external = [
  'fs',
  'path',
  'crypto',
  'stream',
  'lodash/get',
  'lodash/set',
  'lodash/sortBy',
  'openpgp/dist/openpgp.min.js',
  'babel-runtime/regenerator',
  'babel-runtime/helpers/asyncToGenerator',
  'babel-runtime/helpers/classCallCheck',
  'babel-runtime/helpers/createClass',
  'babel-runtime/core-js/promise',
  'babel-runtime/core-js/get-iterator',
  'babel-runtime/helpers/extends',
  'babel-runtime/helpers/typeof',
  'babel-runtime/helpers/slicedToArray',
  'babel-runtime/core-js/math/sign',
  'babel-runtime/core-js/symbol/iterator',
  'babel-runtime/core-js/map',
  'babel-runtime/core-js/object/keys',
  'babel-runtime/helpers/toConsumableArray',
  'babel-runtime/core-js/set',
  ...Object.keys(pkg.dependencies)
]

// Bleeding edge
const moduleConfig = input => ({
  input: `src/${input}`,
  external: [...external, ...codeSplitting(input)],
  output: [{ format: 'es', name: 'git', file: `dist/for-future/${input}` }],
  plugins: [
    json(),
    resolve(),
    babel({
      babelrc: false,
      include: 'node_modules/openpgp/**',
      exclude: 'node_modules/**',
      plugins: ['transform-object-rest-spread']
    }),
    commonjs({
      namedExports: {
        'node_modules/openpgp/src/compression/rawinflate.min.js': 'RawInflate'
      }
    })
  ]
})

// Node.js
const nodeConfig = input => ({
  input: `src/${input}`,
  external: [...external, ...codeSplitting(input)],
  output: [{ format: 'cjs', name: 'git', file: `dist/for-node/${input}` }],
  plugins: [
    json(),
    resolve(),
    babel({
      babelrc: false,
      include: 'node_modules/openpgp/**',
      exclude: 'node_modules/**',
      presets: [
        [
          'env',
          {
            modules: false,
            targets: {
              node: 'current'
            }
          }
        ]
      ],
      plugins: ['external-helpers', 'transform-object-rest-spread']
    })
  ]
})

// Browserify
const browserifyConfig = input => ({
  input: `src/${input}`,
  external: [...external, ...codeSplitting(input)],
  output: [
    { format: 'cjs', name: 'git', file: `dist/for-browserify/${input}` }
  ],
  sourcemap: true,
  plugins: [
    json(),
    resolve(),
    babel({
      babelrc: false,
      include: 'node_modules/openpgp/**',
      exclude: 'node_modules/**',
      presets: [
        [
          'env',
          {
            modules: false,
            targets: {
              browsers: 'last 1 version'
            }
          }
        ]
      ],
      runtimeHelpers: true,
      plugins: ['transform-runtime', 'transform-object-rest-spread']
    })
  ]
})

const inputs = [
  'index.js',
  'commands.js',
  'managers.js',
  'models.js',
  'utils.js'
]

const codeSplitting = input =>
  inputs
    .map(x => path.resolve(`src/${x}`))
    .filter(x => x !== path.resolve(`src/${input}`))

export default [
  ...inputs.map(moduleConfig),
  ...inputs.map(nodeConfig),
  ...inputs.map(browserifyConfig)
]

// package-scripts.js is a convention used by the 'nps' utility
// It's like package.json scripts, but more flexible.
const {concurrent, series, runInNewWindow} = require('nps-utils')

module.exports = {
  scripts: {
    format: 'prettier-standard src/**/*.js test/**/*.js testling/**/*.js *.js',
    lint: 'standard src/**/*.js',
    watch: {
      default: concurrent.nps('watch.rollup', 'watch.ava'),
      rollup: runInNewWindow('rollup -cw'),
      ava: runInNewWindow('ava -w')
    },
    build: {
      default: series.nps('build.rollup', 'build.umd'),
      rollup: 'rollup -c',
      umd: 'browserify --entry dist/for-browserify/index.js --standalone git | uglifyjs > dist/bundle.umd.min.js'
    },
    test: {
      default: series.nps('build', 'test.parallel_tests'),
      parallel_tests: concurrent.nps('test.travis', 'test.travis.karma'),
      travis: {
        default: series.nps('test.travis.ava', 'test.travis.nyc', 'test.travis.codecov'),
        ava: 'ava --tap',
        nyc: 'nyc ava --tap || echo \'nyc failed, no big deal\'',
        codecov: 'nyc report --reporter=lcov > coverage.lcov && codecov || echo \'codecov failed, no big deal\'',
        karma: 'karma start ci.karma.conf.js || echo \'saucelabs failed, no big deal\''
      }
    }
  }
}

