// @flow
import ignore from 'ignore'
import path from 'path'
import { read } from '../utils'

// I'm putting this in a Manager because I reckon it could benefit
// from a LOT of cacheing.

export class GitIgnoreManager {
  static async isIgnored ({
    gitdir,
    workdir,
    pathname
  }) /*: Promise<Boolean> */ {
    let pairs = [
      {
        gitignore: path.join(workdir, '.gitignore'),
        pathname
      }
    ]
    let pieces = pathname.split('/')
    for (let i = 1; i < pieces.length; i++) {
      let dir = pieces.slice(0, i).join('/')
      let file = pieces.slice(i).join('/')
      pairs.push({
        gitignore: path.join(workdir, dir, '.gitignore'),
        pathname: file
      })
    }
    let ignoredStatus = false
    for (let p of pairs) {
      let file
      try {
        file = await read(p.gitignore, 'utf8')
      } catch (err) {
        if (err.code === 'NOENT') continue
      }
      let ign = ignore().add(file)
      // If the parent directory is excluded, we are done.
      // "It is not possible to re-include a file if a parent directory of that file is excluded. Git doesn’t list excluded directories for performance reasons, so any patterns on contained files have no effect, no matter where they are defined."
      // source: https://git-scm.com/docs/gitignore
      let parentdir = path.dirname(p.pathname)
      if (ign.ignores(parentdir)) return true
      // If the file is currently ignored, test for UNignoring.
      if (ignoredStatus) {
        if (
          !ignore()
            .add(`**\n${file}`)
            .ignores(p.pathname)
        ) {
          ignoredStatus = false
        }
      } else {
        ignoredStatus = ign.ignores(p.pathname)
      }
    }
    return ignoredStatus
  }
}

// @flow
import stream from 'stream'
import { getConfig } from './getConfig'
import { GitRemoteHTTP } from '../managers'
import { listCommits } from './listCommits'
import { listObjects } from './listObjects'
import { pack } from './pack'
import { GitPktLine } from '../models'
import { resolveRef } from '../utils'

export async function push ({ gitdir, ref, remote, url, authUsername, authPassword }) {
  // TODO: Figure out how pushing tags works. (This only works for branches.)
  remote = remote || 'origin'
  if (url === undefined) {
    url = await getConfig({
      gitdir,
      path: `remote.${remote}.url`
    })
  }
  let fullRef = ref.startsWith('refs/') ? ref : `refs/heads/${ref}`
  let oid = await resolveRef({ gitdir, ref })
  let httpRemote = new GitRemoteHTTP(url)
  if (authUsername !== undefined && authPassword !== undefined) {
    httpRemote.auth = {
      username: authUsername,
      password: authPassword
    }
  }
  await httpRemote.preparePush()
  let commits = await listCommits({
    gitdir,
    start: [oid],
    finish: httpRemote.refs.values()
  })
  let objects = await listObjects({ gitdir, oids: commits })
  let packstream = new stream.PassThrough()
  let oldoid =
    httpRemote.refs.get(fullRef) || '0000000000000000000000000000000000000000'
  packstream.write(
    GitPktLine.encode(`${oldoid} ${oid} ${fullRef}\0 report-status\n`)
  )
  packstream.write(GitPktLine.flush())
  pack({
    gitdir,
    oids: [...objects],
    outputStream: packstream
  })
  let response = await httpRemote.push(packstream)
  return response
}

