class Git {
  constructor (dir) {
    if (dir) {
      this.workdir = dir
      this.gitdir = `${dir}/.git`
    }
    this.operateRemote = 'origin'
    this.operateDepth = 0
    this.operateBranch = 'master'
  }
  workdir (dir) {
    this.workdir = dir
    return this
  }
  gitdir (dir) {
    this.gitdir = dir
    return this
  }
  githubToken (token) {
    this.operateToken = token
    return this
  }
  remote (name) {
    this.operateRemote = name
    return this
  }
  author (name) {
    this.operateAuthorName = name
    return this
  }
  branch (name) {
    this.operateBranch = name
    return this
  }
  email (email) {
    this.operateAuthorEmail = email
    return this
  }
  datetime (date) {
    this.operateAuthorDateTime = date
    return this
  }
  depth (depth) {
    this.operateDepth = parseInt(depth)
    return this
  }
  timestamp (seconds) {
    // seconds since unix epoch
    this.operateAuthorTimestamp = seconds
    return this
  }
  signingKey (asciiarmor) {
    this.privateKeys = asciiarmor
    return this
  }
  verificationKey (asciiarmor) {
    this.publicKeys = asciiarmor
    return this
  }
  outputStream (stream) {
    this.outputStream = stream
    return this
  }
  inputStream (stream) {
    this.inputStream = stream
    return this
  }
  async init () {
    await init(this.gitdir)
  }
  async fetch (ref) {
    // TODO replace "auth" with just basicAuthUser and basicAuthPassword
    let params = {}
    params.remote = this.operateRemote
    if (this.operateToken) {
      params.auth = {
        username: this.operateToken,
        password: this.operateToken
      }
    }
    params.gitdir = this.gitdir
    params.ref = ref
    params.depth = this.operateDepth
    await fetch(params)
  }
  async checkout (ref) {
    await checkout({
      workdir: this.workdir,
      gitdir: this.gitdir,
      ref,
      remote: this.operateRemote
    })
  }
  async clone (url) {
    await init(this.gitdir)
    // Add remote
    await setConfig({
      gitdir: this.gitdir,
      path: 'remote.origin.url',
      value: url
    })
    // Fetch commits
    let params = {}
    params.remote = this.operateRemote
    if (this.operateToken) {
      params.auth = {
        username: this.operateToken,
        password: this.operateToken
      }
    }
    params.gitdir = this.gitdir
    params.ref = `refs/heads/${this.operateBranch}`
    params.depth = this.operateDepth
    await fetch(params)
    // Checkout branch
    await checkout({
      workdir: this.workdir,
      gitdir: this.gitdir,
      ref: this.operateBranch,
      remote: this.operateRemote
    })
  }
  async list () {
    return list({
      gitdir: this.gitdir
    })
  }
  async add (filepath) {
    return add({
      gitdir: this.gitdir,
      workdir: this.workdir,
      filepath
    })
  }
  async remove (filepath) {
    return remove({
      gitdir: this.gitdir,
      filepath
    })
  }
  async commit (message) {
    return commit({
      gitdir: this.gitdir,
      author: {
        name: this.operateAuthorName || (await this.getConfig('user.name')),
        email: this.operateAuthorEmail || (await this.getConfig('user.email')),
        timestamp: this.operateAuthorTimestamp,
        date: this.operateAuthorDateTime
      },
      committer: {
        name: this.operateAuthorName || (await this.getConfig('user.name')),
        email: this.operateAuthorEmail || (await this.getConfig('user.email')),
        timestamp: this.operateAuthorTimestamp,
        date: this.operateAuthorDateTime
      },
      message,
      privateKeys: this.privateKeys
    })
  }
  async verify (ref) {
    return verify({
      gitdir: this.gitdir,
      publicKeys: this.publicKeys,
      ref
    })
  }
  async pack (oids) {
    return pack({
      gitdir: this.gitdir,
      outputStream: this.outputStream,
      oids
    })
  }
  async unpack (oids) {
    return unpack({
      gitdir: this.gitdir,
      inputStream: this.inputStream
    })
  }
  async push (ref) {
    let url = await getConfig({
      gitdir: this.gitdir,
      path: `remote.${this.operateRemote}.url`
    })
    console.log('url =', url)
    return push({
      gitdir: this.gitdir,
      ref,
      url,
      auth: {
        username: this.operateToken,
        password: this.operateToken
      }
    })
  }
  async pull (ref) {
    let params = {}
    params.remote = this.operateRemote
    if (this.operateToken) {
      params.auth = {
        username: this.operateToken,
        password: this.operateToken
      }
    }
    params.gitdir = this.gitdir
    params.ref = ref
    return fetch(params)
  }
  async getConfig (path) {
    return getConfig({
      gitdir: this.gitdir,
      path
    })
  }
  async setConfig (path, value) {
    return setConfig({
      gitdir: this.gitdir,
      path,
      value
    })
  }
  async status (pathname) {
    return status({
      gitdir: this.gitdir,
      workdir: this.workdir,
      pathname
    })
  }
}

