import { init } from './init'
import { setConfig } from './setConfig'
import { fetch } from './fetch'
import { checkout } from './checkout'

export async function clone ({
  workdir,
  gitdir,
  url,
  remote,
  ref,
  depth,
  authUsername,
  authPassword
}) {
  remote = remote || 'origin'
  await init({gitdir})
  // Add remote
  await setConfig({
    gitdir,
    path: `remote.${remote}.url`,
    value: url
  })
  // Fetch commits
  await fetch({
    gitdir,
    ref,
    depth,
    remote,
    authUsername,
    authPassword
  })
  // Checkout branch
  await checkout({
    workdir,
    gitdir,
    ref,
    remote
  })
}

const { exec } = require('child_process')
const url = require('url')
const stream = require('stream')
const parseHeaderStream = require('parse-header-stream')
const path = require('path')

module.exports = function (rootDir) {
  async function request (method, rawUrl, postStream, requestHeaders) {
    let parsedUrl = url.parse(rawUrl)
    let options = {
      env: {
        REQUEST_METHOD: method,
        GIT_PROJECT_ROOT: rootDir,
        PATH_INFO: parsedUrl.pathname, // '/test-GitRemoteHTTP.git/info/refs',
        REMOTE_USER: 'mrtest@example.com',
        // REMOTE_ADDR,
        CONTENT_TYPE: requestHeaders['Content-Type'],
        QUERY_STRING: parsedUrl.query // 'service=git-receive-pack'
      }
    }
    let proc = exec('git http-backend', options)
    if (postStream && typeof postStream.pipe === 'function') {
      postStream.pipe(proc.stdin)
    }
    const body = new stream.PassThrough()
    let waitForHeaders = new Promise(function (resolve, reject) {
      proc.stdout
        .pipe(
          parseHeaderStream(function (err, headers) {
            if (err) reject(err)
            else resolve(headers)
          })
        )
        .on('body', function (_body) {
          _body.pipe(body)
        })
    })
    let headers = await waitForHeaders
    return { body, headers }
  }

  // Note: we lose the headers :(
  function get (uri, requestBody, cb) {
    request('GET', uri, requestBody, {}).then(({ body, headers }) =>
      cb(null, body)
    )
  }

  // Note: we lose the headers :(
  function postReceivePackRequest (uri, requestBody, cb) {
    let buf = Buffer.from(requestBody, 'hex')
    let postStream = new stream.PassThrough()
    postStream.end(buf)
    request('POST', uri, postStream, {
      'Content-Type': 'application/x-git-receive-pack-request'
    }).then(({ body, headers }) => cb(null, body))
  }

  // Note: we lose the headers :(
  function postUploadPackRequest (uri, requestBody, cb) {
    let buf = Buffer.from(requestBody, 'hex')
    let postStream = new stream.PassThrough()
    postStream.end(buf)
    request('POST', uri, postStream, {
      'Content-Type': 'application/x-git-upload-pack-request'
    }).then(({ body, headers }) => cb(null, body))
  }

  return {
    request,
    get,
    postReceivePackRequest,
    postUploadPackRequest
  }
}

import { getConfig } from './getConfig'
import { GitCommit, GitTree } from '../models'
import { GitObjectManager, GitIndexManager } from '../managers'
import { write, resolveRef, flatFileListToDirectoryStructure } from '../utils'
import path from 'path'

async function constructTree ({ gitdir, inode }) /*: string */ {
  // use depth first traversal
  let children = inode.children
  for (let inode of children) {
    if (inode.type === 'tree') {
      inode.metadata.mode = '040000'
      inode.metadata.oid = await constructTree({ gitdir, inode })
    }
  }
  let entries = children.map(inode => ({
    mode: inode.metadata.mode,
    path: inode.basename,
    oid: inode.metadata.oid,
    type: inode.type
  }))
  const tree = GitTree.from(entries)
  let oid = await GitObjectManager.write({
    gitdir,
    type: 'tree',
    object: tree.toObject()
  })
  return oid
}

export async function commit ({
  gitdir,
  author,
  committer,
  message,
  privateKeys
}) {
  // Fill in missing arguments with default values
  if (author === undefined) author = {}
  if (author.name === undefined) { author.name = await getConfig({ gitdir, path: 'user.name' }) }
  if (author.email === undefined) { author.email = await getConfig({ gitdir, path: 'user.email' }) }
  committer = committer || author
  let authorDateTime = author.date || new Date()
  let committerDateTime = committer.date || authorDateTime
  let oid
  await GitIndexManager.acquire(`${gitdir}/index`, async function (index) {
    const inode = flatFileListToDirectoryStructure(index.entries)
    const treeRef = await constructTree({ gitdir, inode })
    let parents
    try {
      let parent = await resolveRef({ gitdir, ref: 'HEAD' })
      parents = [parent]
    } catch (err) {
      // Probably an initial commit
      parents = []
    }
    let comm = GitCommit.from({
      tree: treeRef,
      parent: parents,
      author: {
        name: author.name,
        email: author.email,
        timestamp:
          author.timestamp || Math.floor(authorDateTime.valueOf() / 1000),
        timezoneOffset: author.timezoneOffset || 0
      },
      committer: {
        name: committer.name,
        email: committer.email,
        timestamp:
          committer.timestamp || Math.floor(committerDateTime.valueOf() / 1000),
        timezoneOffset: committer.timezoneOffset || 0
      },
      message
    })
    if (privateKeys) {
      comm = await comm.sign(privateKeys)
    }
    oid = await GitObjectManager.write({
      gitdir,
      type: 'commit',
      object: comm.toObject()
    })
    // Update branch pointer
    const branch = await resolveRef({ gitdir, ref: 'HEAD', depth: 2 })
    await write(path.join(gitdir, branch), oid + '\n')
  })
  return oid
}

